S={"ng":{"country":"Nigeria","src":{"label":"UK government (APHA) — export health certificate 3713 for cats and dogs to Nigeria (UK-side page, certificate wording agreed 2010)","url":"https://www.gov.uk/export-health-certificates/export-cats-and-dogs-to-nigeria-certificate-3713"},
"head":"The UK certificate for Nigeria needs a rabies antibody test of 0.5 IU/ml and a vet exam within 48 hours of export.",
"lines":["The UK's APHA publishes the certificate its vets sign for pets going to Nigeria. It says the animal is examined within 48 hours of export and found free of infectious disease, rabies and external parasites.","The pet must have a rabies vaccine given at 3 months or older and within a year of export (unless a timely booster), and a blood test showing at least 0.5 IU/ml of rabies antibody, taken 3 to 24 months before export at a government or authorised lab.","The certificate is valid for 7 days after signature and has a space for an import permit number if one applies. This is a UK-side page whose certificate dates from 2010, so confirm current Nigerian rules with the Nigerian authority."]}}
for k,v in S.items(): json.dump(v,open('dup_work/petspecs/%s.json'%k,'w',encoding='utf8'),ensure_ascii=False,separators=(',',':'))
